export function o_fields(o) { return [o.a, o.b]; }
export function o_named(o) { return [o.a, o.b, "a" in Object(o)]; }
export function o_write(o) { o.a = "written"; o.fresh = 1; return Object.keys(o); }
export function o_delete(o) { delete o.a; return [o.a, Object.keys(o)]; }
export function o_method(o) { return o.m(1); }
export function o_nested(o) { return o.inner.a; }
export function o_array(list) { let sum = 0; for (let i = 0; i < list.length; i++) sum += list[i]; return [sum, list.length]; }
export function o_array_methods(list) { return list.map((x) => x + 1); }
export function o_array_push(list) { list.push("pushed"); return list.length; }
export function o_for_of(list) { const seen = []; for (const x of list) seen.push(x); return seen; }
export function o_tuple(pair) { return [pair[0], pair[1], pair.length]; }
export function o_callback(f) { return f(1, 2); }
export function o_map(m) { return [m.get("a"), m.size, m.has("a")]; }
export function o_set(s) { return [s.has(1), s.size]; }
export function o_date(d) { return d.getTime(); }
export function o_regexp(r) { return r.test("a"); }
export function o_promise(p) { return typeof p.then; }
export function o_url(u) { return [u.pathname, u.href]; }
export function o_request(r) { return [r.url, r.method]; }
export function o_bytes(b) { return [b[0], b.length, b.byteLength]; }
export function o_record(r) { return [r.a, r["b"], Object.keys(r)]; }
export function o_object(o) { return Object.keys(o); }
